package com.ruoyi.medical.persistence;

import com.ruoyi.medical.identity.IdentityDirectoryPolicy;
import com.ruoyi.medical.persistence.mapper.*;
import javax.sql.DataSource;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/** Explicit N01 business lane; no fallback mocks or implicitly enabled PLAN_DRAFT endpoints. */
@Configuration
@ConditionalOnProperty(name="medical.professional-runtime.plan-draft-enabled",havingValue="true",matchIfMissing=false)
public class TaskPlanDraftBusinessConfiguration {
    @Bean TaskPlanDraftSchema taskPlanDraftSchema()throws Exception{return new TaskPlanDraftSchema();}
    @Bean TaskPlanDraftCandidatePolicy taskPlanDraftCandidatePolicy(TaskPlanPolicy plans,PermissionSchema json){return new TaskPlanDraftCandidatePolicy(plans,json);}
    @Bean TaskPlanDraftAdmission taskPlanDraftAdmission(TaskService tasks,TaskPlanService plans,ProjectService projects,TemplateApplicabilityService templates,
            ResourceReadAuthority resources,AgentReleaseStore releases,AgentReleaseScopeAuthority scopes,TemplateDependencyPolicy limits,
            IdentityDirectoryPolicy identities,RunCreateBudget budgets,PermissionMapper permissions,PermissionSchema json,TaskPlanDraftSchema schema,
            VersionResourceMapper owners,DependencyLineage lineage,RuntimeRetentionAuthority retention){return new TaskPlanDraftAdmission(tasks,plans,projects,templates,resources,releases,scopes,limits,identities,budgets,permissions,json,schema,owners,lineage,retention);}
    @Bean TaskPlanDraftProducerAuthority taskPlanDraftProducerAuthority(FormalCapabilityIdentityAuthority capabilities,PermissionSchema json,TaskPlanDraftSchema schema,PermissionMapper clock,DataSource data,TaskPlanDraftJobs jobs)throws Exception{return new TaskPlanDraftProducerAuthority(capabilities,json,schema,clock,data,jobs);}
    @Bean TaskPlanDraftCurrentAccess taskPlanDraftCurrentAccess(TaskPlanDraftJobs jobs,TaskPlanDraftAdmission admission,TaskPlanDraftJobAuthority authority,AgentPublicationAuthority publication,AgentExecutionPolicyAuthority policy){return new TaskPlanDraftCurrentAccess(jobs,admission,authority,publication,policy);}
    @Bean TaskPlanDraftContentAuthority taskPlanDraftContentAuthority(DependencyLineage lineage,VersionResourceMapper owners,TemplateDependencyPolicy limits){return new TaskPlanDraftContentAuthority(lineage,owners,limits.limits());}
    @Bean TaskPlanDraftObjectLedger taskPlanDraftObjectLedger(DataSource data,TaskPlanDraftSchema schema,TaskPlanDraftJobs jobs,TaskPlanDraftProducerAuthority producers,TaskPlanDraftJobAuthority authority){return new TaskPlanDraftObjectLedger(data,schema,jobs,producers,authority);}
    @Bean TaskPlanDraftObjectRegistration taskPlanDraftObjectRegistration(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,DependencyManifestSchema manifests,TaskPlanDraftObjectLedger ledger,TaskPlanDraftContentAuthority content){return new TaskPlanDraftObjectRegistration(data,schema,json,manifests,ledger,content);}
    @Bean TaskPlanDraftCandidateNormalizer taskPlanDraftCandidateNormalizer(TaskPlanDraftCandidatePolicy policy,TaskPlanDraftSchema schema,PermissionSchema json)throws Exception{return new TaskPlanDraftCandidateNormalizer(policy,schema,json);}
    @Bean TaskPlanDraftCandidateRegistration taskPlanDraftCandidateRegistration(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftObjectLedger ledger,TaskPlanDraftContentAuthority content)throws Exception{return new TaskPlanDraftCandidateRegistration(data,schema,json,ledger,content);}
    @Bean TaskPlanDraftIndependentCheck taskPlanDraftIndependentCheck(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftCandidatePolicy policy,TaskPlanService plans,PermissionMapper permissions,TemplateMapper templates,ResourceReadAuthority resources)throws Exception{return new TaskPlanDraftIndependentCheck(data,schema,json,policy,plans,permissions,templates,resources);}
    @Bean TaskPlanDraftSaveAction taskPlanDraftSaveAction(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,RunTokenAuthoritySchema runtime,FormalCapabilityIdentityAuthority capabilities)throws Exception{return new TaskPlanDraftSaveAction(data,schema,json,runtime,capabilities);}
    @Bean TaskPlanDraftSaveReceipt taskPlanDraftSaveReceipt(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftSaveAction actions)throws Exception{return new TaskPlanDraftSaveReceipt(data,schema,json,actions);}
    @Bean TaskPlanDraftHistoricalAccess taskPlanDraftHistoricalAccess(TaskPlanDraftJobs jobs,TaskService tasks,TaskPlanService plans,TemplateApplicabilityService templates,ProjectService projects,ResourceReadAuthority resources,TaskPlanDraftSchema schema,PermissionSchema json){return new TaskPlanDraftHistoricalAccess(jobs,tasks,plans,templates,projects,resources,schema,json);}
    @Bean TaskPlanDraftPackagePreflight taskPlanDraftPackagePreflight(EnterpriseAccess access,FormalCapabilityIdentityAuthority capabilities,ArtifactContentService content,SourceUploadTransport objects,ArtifactRegistryMapper artifacts,SourceReadMapper sources,DependencyLineage lineage,AgentPublicationDependencies dependencies,EvaluationReferences profiles,EvaluationDependencyPolicy policy,PermissionSchema json)throws Exception{return new TaskPlanDraftPackagePreflight(access,capabilities,new FormalEvaluationContextPackages(access,content,objects,artifacts,sources,lineage,dependencies,profiles,policy,json),json);}
    @Bean TaskPlanDraftService taskPlanDraftService(DataSource data,EnterpriseAccess access,TaskService tasks,TaskPlanService plans,ResourceReadAuthority resources,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftAdmission admission,TaskPlanDraftJobs jobs,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,TaskPlanDraftPackagePreflight packages,TaskPlanDraftSavedCandidate candidates,TaskPlanDraftHumanCheck checks,TaskPlanDraftSavedToolReceipt tools)throws Exception{return new TaskPlanDraftService(data,access,tasks,plans,resources,schema,json,admission,jobs,publications,policies,packages,candidates,checks,tools);}
    @Bean TaskPlanDraftSavedCandidate taskPlanDraftSavedCandidate(DataSource data,EnterpriseAccess access,TaskPlanDraftHistoricalAccess historical,TaskPlanDraftSupervisor supervisor,TaskPlanDraftDeployment deployment,TaskPlanDraftInvocationService invocations,TaskPlanDraftCandidateNormalizer normalizer,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftCandidateRegistration candidates,ArtifactRegistry registry,ArtifactSourceAuthority sourceAuthority,SourceReadMapper sources,TemplateDependencyPolicy limits,SourceUploadTransport transport)throws Exception{return new TaskPlanDraftSavedCandidate(data,access,historical,supervisor,deployment,invocations,normalizer,schema,json,candidates,registry,sourceAuthority,sources,limits,transport);}
    @Bean TaskPlanDraftHumanCheck taskPlanDraftHumanCheck(DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftCandidatePolicy policy,TaskPlanService plans,PermissionMapper permissions,TemplateMapper templates,ResourceReadAuthority resources)throws Exception{return new TaskPlanDraftHumanCheck(data,schema,json,policy,plans,permissions,templates,resources);}
    @Bean TaskPlanDraftSavedToolReceipt taskPlanDraftSavedToolReceipt(DataSource data,TaskPlanDraftSchema schema){return new TaskPlanDraftSavedToolReceipt(data,schema);}
    @Bean TaskPlanDraftOriginGuard taskPlanDraftOriginGuard(EnterpriseAccess access,TaskPlanDraftOriginLocator locator,TaskPlanDraftSavedCandidate candidates,TaskPlanDraftSavedToolReceipt tools,TaskPlanDraftHumanCheck checks,TaskPlanDraftSchema schema,PermissionSchema json){return new TaskPlanDraftOriginGuard(access,locator,candidates,tools,checks,schema,json);}
}
